export function findById(id){return CAMPAIGNS.find(x=>x.id===id)}
export function search(q){const s=String(q||'').toLowerCase();if(!s)return CAMPAIGNS.slice();return CAMPAIGNS.filter(x=>JSON.stringify(x).toLowerCase().includes(s))}
export function enabledOnly(){return CAMPAIGNS.filter(x=>x.enabled!==false)}
export const COUNT=CAMPAIGNS.length;

